function predict(value){if(phase!=='predict')return;prediction=value;if(advanced()&&current().assessmentSource==='analysis'){$('endgameFeedback').textContent='Для этой позиции указана предварительная оценка движка. Сравните свой прогноз с разбором; оценка не является табличным доказательством.';render();return}$('endgameFeedback').textContent=value===expectedAnswer()?'Верно. Теперь проверьте оценку на доске.':'Попробуем разобраться на доске. После партии сравним результат с правилом урока.';render()}
function chooseRookReply(){const moves=game.moves({verbose:true}).filter(m=>!m.promotion||['q','r'].includes(m.promotion)),attacker=pawnColor(),attacks=game.turn()===attacker;const rated=moves.map(m=>{const probe=new Chess(game.fen());probe.move(m);return {m,info:window.RookPawnOracle.evaluate(probe)}});const target=attacks?rated.some(x=>x.info.win):rated.every(x=>x.info.win);const eligible=rated.filter(x=>x.info.win===target);const history=game.history(),example=current().linesByTurn?.[initialTurn]||(initialTurn===defaultTurn(current())?current().line||[]:[]);if(history.every((m,i)=>m===example[i])){const book=eligible.find(x=>x.m.san===example[history.length]);if(book)return book.m}if(target){eligible.sort((a,b)=>attacks?a.info.distance-b.info.distance:b.info.distance-a.info.distance);return eligible[0]?.m}const pawn=findPiece('p',attacker);if(!pawn)return eligible.find(x=>x.m.captured)?.m||eligible[0]?.m;const corner=pawn[0]+(attacker==='b'?'1':'8');const score=m=>attacks?(m.piece==='p'?-15:Number(m.to[1])*(attacker==='b'?1:-1)+distance(m.to,corner)):(m.captured?-100:distance(m.to,corner)*10);const best=Math.min(...eligible.map(x=>score(x.m)));const ties=eligible.filter(x=>score(x.m)===best);return ties[Math.floor(Math.random()*ties.length)]?.m}
function chooseOpposedReply(){const side=game.turn(),score=info=>info.winner===side?1:info.winner===null?0:-1,rated=game.moves({verbose:true}).map(m=>{game.move(m);const info=game.isDraw()?{winner:null,distance:0}:window.OpposedPawnOracle.evaluate(game);game.undo();return {m,info}});if(!rated.length)return null;const best=Math.max(...rated.map(x=>score(x.info))),eligible=rated.filter(x=>score(x.info)===best),history=game.history(),example=current().linesByTurn?.[initialTurn]||(initialTurn===defaultTurn(current())?current().line||[]:[]);if(history.every((m,i)=>m===example[i])){const book=eligible.find(x=>x.m.san===example[history.length]);if(book)return book.m}const zero=m=>m.piece==='p'||m.captured;const dtz=x=>zero(x.m)?1:x.info.distance+1;if(best!==0){eligible.sort((a,b)=>best>0?dtz(a)-dtz(b):dtz(b)-dtz(a));return eligible[0].m}const pawn=findPiece('p',side==='w'?'b':'w'),promotion=findPiece('p',side);const plan=m=>m.captured?-100:m.piece==='p'?-20:pawn?distance(m.to,pawn)*5:promotion?distance(m.to,promotion):0;eligible.sort((a,b)=>plan(a.m)-plan(b.m));return eligible[0].m}
